import React, { useEffect, useState } from 'react';
import Shimmer from './Shimmer';
import Error from './Error'

const EffectCard = () => {
    const [products, setProducts] = useState([]);
    let [isLoading, setIsLoading] = useState(false);
    let [error, setError] = useState("");
    let [searchText, setSearchText] = useState("");
    let [filteredProducts, setFilteredProducts] = useState([]);

    function handleSearch() {
        let filtered = products.filter((product) => product.brand.toLowerCase().includes(searchText.toLowerCase()))
        setFilteredProducts(filtered)
    }

    function handleCategory(e) {
        if (e.target.name === 'Gaming') {
            let filtered = products.filter((product) => product.category === 'gaming')
            setFilteredProducts(filtered)
        }
        else if (e.target.name === 'Music') {
            let filtered = products.filter((product) => product.category === 'audio')
            setFilteredProducts(filtered)
        }
        else if (e.target.name === 'Mobile') {
            let filtered = products.filter((product) => product.category === 'mobile')
            setFilteredProducts(filtered)
        }
        else if (e.target.name === 'Tv') {
            let filtered = products.filter((product) => product.category === 'tv')
            setFilteredProducts(filtered)
        }
    }

    async function getData() {
        try {
            let res = await fetch('https://fakestoreapi.in/api/products')
            let data = await res.json()
            setProducts(data.products)
            setFilteredProducts(data.products)
        } catch (error) {
            setError(error.message)
        }
        finally {
            setIsLoading(true)
        }
    }

    useEffect(() => {
        getData();
    }, []);

    return (
        <div className="container mt-4">
            <section>
                <div className="container-fluid mt-3">
                    <div className="row">
                        <div className="col d-flex justify-content-center align-items-center mb-3">
                            <button className='btn badge badge-primary btn-sm badge-pill btn-primary' name='Gaming' onClick={handleCategory}>Gaming</button>
                            <button className='btn badge badge-success btn-sm badge-pill btn-primary' name='Music' onClick={handleCategory}>Music</button>
                            <button className='btn badge badge-danger btn-sm badge-pill btn-primary' name='Mobile' onClick={handleCategory}>Mobile</button>
                            <button className='btn badge badge-warning btn-sm badge-pill btn-primary' name='Tv' onClick={handleCategory}>Tv</button>
                            <input type="text" className="form-control" placeholder='Search' value={searchText} onChange={(e) => { setSearchText(e.target.value) }} />
                            <button className='btn btn-primary btn-md badge badge-success' onClick={handleSearch}>Search</button>
                        </div>
                    </div>
                </div>
            </section>
            <div className="row g-4">
                {!isLoading && <Shimmer />}
                {isLoading && !error && filteredProducts.map((product) => (
                    <div className="col-md-4" key={product.id}>
                        <div className="card h-100 border-0 shadow rounded-4">
                            <img src={product.image} alt="Invalid" className="img-fluid p-4" />
                            <div className="card-body">
                                <h5 className="card-title fw-semibold text-uppercase">{product.brand}</h5>
                                <h5 className="card-title fw-light"><pre className='fs-6 badge badge-warning'>{product.category}</pre></h5>
                                <h5 className="card-title fw-light"><pre className='fs-6 text-wrap'>{product.title}</pre></h5>
                            </div>
                            <div className="card-footer bg-white border-top-0">
                                <h6 className="text-success fw-bold fs-4 badge badge-success badge-pill">₹{product.price}</h6>
                                <div className="text-center">
                                    <button className='btn btn-primary btn-lg badge badge-info'>Add to Cart</button>
                                </div>
                            </div>
                        </div>
                    </div>
                ))}
                {console.log(error)}
                {error && <Error message={error} />}
            </div>
        </div>
    );
};

export default EffectCard;
